const root=document.querySelector('#network');
const $=s=>root.querySelector(s), $$=s=>[...root.querySelectorAll(s)];
let universities=[],region='All',selected=null,flyTo=null,lastTrigger=null,ready=false;
const input=$('#university-search'), list=$('#university-list'), card=$('#university-card');
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
let manualPause=reduce.matches, inactiveUntil=0, visible=false, intersected=false;
function activeMotion(){return !manualPause&&!reduce.matches&&!document.body.classList.contains('motion-off');}
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n;}
function logo(u,cls){if(!u.logo)return null;const im=el('img',cls);im.src=u.logo;im.alt=u.name+' logo';im.dataset.school=u.id;im.loading='eager';im.addEventListener('error',()=>{im.replaceWith(el('span','list-dot'));});return im;}
function matches(u){const q=input.value.trim().toLowerCase();return q?[u.name,u.short,u.city,u.country,...(u.aliases||[])].join(' ').toLowerCase().includes(q):region==='All'||u.region===region||(region==='United States'&&u.country==='United States');}
function renderList(){const results=universities.filter(matches);list.replaceChildren();$('#university-count').textContent=results.length+' / '+universities.length;$('#region-title').textContent=input.value.trim()?'SEARCH RESULTS':region.toUpperCase()+' UNIVERSITIES';$('.global-empty').hidden=results.length>0;list.hidden=!results.length;
 results.forEach(u=>{const b=el('button');b.type='button';b.dataset.university=u.id;b.setAttribute('aria-pressed',String(selected?.id===u.id));b.append(logo(u,'list-logo')||el('span','list-dot'));const t=el('span');t.append(el('strong',null,u.name),el('small',null,u.city+' · '+u.country));b.append(t,el('span','list-arrow','↗'));b.addEventListener('click',()=>choose(u,b));list.append(b);});}
function closeCard(restore=false){card.hidden=true;selected=null;if(restore&&lastTrigger?.isConnected)lastTrigger.focus();renderList();}
function choose(u,trigger){selected=u;lastTrigger=trigger;window.IMN_SELECTED_UNIVERSITY=u.name;inactiveUntil=performance.now()+12000;$('.global-card-logo').replaceChildren(logo(u)||el('span',null,u.short));$('#university-card-title').textContent=u.name;$('.global-card-location').textContent=u.city+', '+u.country;const available=u.mentorStatus==='available'&&u.mentorUrl;
 $('.global-card-status').textContent=available?'Mentors available':'Tell us your preferred university on an informational call.';$('.global-card-cta').hidden=false;$('.global-card-cta').href=available?u.mentorUrl:'https://cal.com/todiq-vasquez/informational-meeting';$('.global-card-cta').innerHTML=available?'EXPLORE MENTORS <span>↗</span>':'BOOK AN INFORMATIONAL CALL <span>↗</span>';$('.global-card-coming').hidden=true;card.hidden=false;renderList();if(flyTo)flyTo(u.lat,u.lng,2.05);$('.global-card-close').focus({preventScroll:true});if(matchMedia('(max-width:760px)').matches)card.scrollIntoView({behavior:reduce.matches?'instant':'smooth',block:'nearest'});}
$('.global-card-close').addEventListener('click',()=>closeCard(true));document.addEventListener('pointerdown',e=>{if(!card.hidden&&!card.contains(e.target)&&!e.target.closest('.globe-marker')&&!e.target.closest('[data-university]'))closeCard();});root.addEventListener('keydown',e=>{if(e.key==='Escape')closeCard(true);});
input.addEventListener('input',()=>{closeCard();renderList();});input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();list.querySelector('button')?.focus();}if(e.key==='Enter'){const u=universities.find(matches);if(u)choose(u,input);}});
const centers={'United States':[39,-96,2.7],'All':[25,-35,4.25],'North America':[39,-96,2.7],'Europe':[50,9,2.5],'Asia':[28,112,2.8],'Middle East':[25.3,51.44,2.5],'Oceania':[-30,143,2.7]};
$$('[data-region]').forEach(b=>b.addEventListener('click',()=>{region=b.dataset.region;input.value='';closeCard();$$('[data-region]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderList();if(flyTo)flyTo(...centers[region]);}));
$('#globe-motion').addEventListener('click',()=>{manualPause=!manualPause;syncMotion();});function syncMotion(){$('#globe-motion').textContent=manualPause?'Resume rotation':'Pause rotation';$('#globe-motion').setAttribute('aria-pressed',String(manualPause));}reduce.addEventListener('change',()=>{manualPause=reduce.matches;syncMotion();});syncMotion();
function fallback(message){root.classList.add('globe-fallback','globe-entered');$('.globe-loading').hidden=false;$('.globe-loading').textContent=message;$('#globe-help').textContent='Search or choose a university from the list to explore its details.';}
async function init(){try{const res=await fetch('/network/universities.json');if(!res.ok)throw Error('Dataset unavailable');universities=await res.json();renderList();}catch{fallback('The university directory could not load. Please refresh to try again.');return;}
 const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible&&!intersected){intersected=true;root.classList.add('globe-entered');startGlobe().catch(()=>fallback('The 3D globe is unavailable on this browser. You can explore all universities using the search, region filters, and list.'));}},{rootMargin:'200px'});observer.observe(root);
}
async function startGlobe(){const [THREE,{OrbitControls},world]=await Promise.all([import('./vendor/three.module.js'),import('./vendor/OrbitControls.js'),fetch('/network/countries.json').then(r=>{if(!r.ok)throw Error();return r.json();})]);
 const view=$('#globe-view'),container=$('#globe-canvas');let renderer;try{renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});}catch{throw Error('WebGL unsupported');}
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setClearColor(0,0);container.append(renderer.domElement);renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();fallback('3D rendering paused. Please refresh to restore the globe, or continue using the university list.');ready=false;});
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(34,1,.05,50);const vec=(lat,lng,r=1)=>{let a=lat*Math.PI/180,b=lng*Math.PI/180;return new THREE.Vector3(Math.cos(a)*Math.cos(b)*r,Math.sin(a)*r,-Math.cos(a)*Math.sin(b)*r);};camera.position.copy(vec(25,-35,4.25));
 const controls=new OrbitControls(camera,renderer.domElement);controls.enablePan=false;controls.enableDamping=true;controls.dampingFactor=.07;controls.rotateSpeed=.6;controls.zoomSpeed=.65;controls.minDistance=1.35;controls.maxDistance=6.2;controls.autoRotateSpeed=.16;controls.minPolarAngle=.12;controls.maxPolarAngle=Math.PI-.12;
 let transition=null;controls.addEventListener('start',()=>{transition=null;inactiveUntil=performance.now()+8000;});controls.addEventListener('end',()=>inactiveUntil=performance.now()+6000);
 flyTo=(lat,lng,distance)=>{inactiveUntil=performance.now()+10000;const from=camera.position.clone(),to=vec(lat,lng,distance);transition={from:from.clone().normalize(),to:to.clone().normalize(),a:from.length(),b:distance,t:performance.now()};if(reduce.matches){camera.position.copy(to);controls.update();transition=null;}};
 const texCanvas=document.createElement('canvas');texCanvas.width=2048;texCanvas.height=1024;const ctx=texCanvas.getContext('2d');ctx.fillStyle='#a9bba1';ctx.fillRect(0,0,2048,1024);ctx.strokeStyle='#98ad90';ctx.lineWidth=.65;for(let lng=-180;lng<=180;lng+=30){let x=(lng+180)/360*2048;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,1024);ctx.stroke();}for(let lat=-60;lat<=60;lat+=30){let y=(90-lat)/180*1024;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(2048,y);ctx.stroke();}
 ctx.fillStyle='#ecebd6';ctx.strokeStyle='#b6c1a8';ctx.lineWidth=.65;for(const f of world.features){const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;for(const poly of polys){ctx.beginPath();for(const ring of poly){ring.forEach(([lng,lat],i)=>{const x=(lng+180)/360*2048,y=(90-lat)/180*1024;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.closePath();}ctx.fill('evenodd');ctx.stroke();}}
 const tex=new THREE.CanvasTexture(texCanvas);tex.colorSpace=THREE.SRGBColorSpace;tex.anisotropy=Math.min(renderer.capabilities.getMaxAnisotropy(),4);
 const sphere=new THREE.Mesh(new THREE.SphereGeometry(1,96,64),new THREE.MeshStandardMaterial({map:tex,roughness:.95,metalness:0}));scene.add(sphere);scene.add(new THREE.AmbientLight(0xf8f6e8,2));const sun=new THREE.DirectionalLight(0xfffae9,2.2);sun.position.set(-3,5,4);camera.add(sun);scene.add(camera);
 const markerLayer=$('#globe-labels'),markers=[];universities.forEach(u=>{const b=el('button','globe-marker');b.type='button';b.tabIndex=-1;b.title=u.name;b.setAttribute('aria-label',u.name);b.append(logo(u)||el('span','marker-name',u.short),el('span','marker-tooltip',u.name));b.addEventListener('click',e=>{e.stopPropagation();choose(u,b);});markerLayer.append(b);markers.push({u,b,pos:vec(u.lat,u.lng,1.012)});});
 const routes=[['harvard','oxford'],['stanford','cambridge'],['penn','caltech'],['yale','princeton'],['cornell','johns-hopkins']];const lines=[];for(const [a,b] of routes){const u=universities.find(x=>x.id===a),v=universities.find(x=>x.id===b);if(!u||!v)continue;const from=vec(u.lat,u.lng),to=vec(v.lat,v.lng),angle=from.angleTo(to),points=[];for(let i=0;i<=90;i++){const t=i/90;const p=from.clone().multiplyScalar(Math.sin((1-t)*angle)).add(to.clone().multiplyScalar(Math.sin(t*angle))).divideScalar(Math.sin(angle));p.multiplyScalar(1.012+Math.sin(Math.PI*t)*.15);points.push(p);}const geo=new THREE.BufferGeometry().setFromPoints(points);const material=new THREE.LineDashedMaterial({color:0x617953,transparent:true,opacity:0,dashSize:.035,gapSize:.018});const line=new THREE.Line(geo,material);line.computeLineDistances();scene.add(line);lines.push(line);}
 const resize=()=>{let w=view.clientWidth,h=view.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();};new ResizeObserver(resize).observe(view);resize();
 const zoom=f=>{inactiveUntil=performance.now()+7000;transition=null;camera.position.multiplyScalar(f).clampLength(controls.minDistance,controls.maxDistance);controls.update();};$('#globe-zoom-in').addEventListener('click',()=>zoom(.83));$('#globe-zoom-out').addEventListener('click',()=>zoom(1.2));$('#globe-reset').addEventListener('click',()=>flyTo(...centers[region]));view.addEventListener('keydown',e=>{if(e.target!==view)return;let sp=new THREE.Spherical().setFromVector3(camera.position),step=.13;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'].includes(e.key)){e.preventDefault();transition=null;inactiveUntil=performance.now()+7000;if(e.key==='ArrowLeft')sp.theta-=step;if(e.key==='ArrowRight')sp.theta+=step;if(e.key==='ArrowUp')sp.phi-=step;if(e.key==='ArrowDown')sp.phi+=step;if(e.key==='+'||e.key==='=')sp.radius*=.83;if(e.key==='-')sp.radius*=1.2;sp.phi=Math.max(.12,Math.min(Math.PI-.12,sp.phi));sp.radius=Math.max(1.35,Math.min(6.2,sp.radius));camera.position.setFromSpherical(sp);controls.update();}});
 $('.globe-loading').hidden=true;ready=true;const born=performance.now();let previous=born;
 function frame(now){requestAnimationFrame(frame);if(!ready||!visible||document.hidden){previous=now;return;}const dt=Math.min((now-previous)/1000,.05);previous=now;controls.autoRotate=activeMotion()&&!transition&&now>inactiveUntil&&!selected;
 if(transition){let t=Math.min(1,(now-transition.t)/1400),ease=t*t*(3-2*t),angle=transition.from.angleTo(transition.to),p;if(angle<.0001)p=transition.to.clone();else p=transition.from.clone().multiplyScalar(Math.sin((1-ease)*angle)).add(transition.to.clone().multiplyScalar(Math.sin(ease*angle))).divideScalar(Math.sin(angle));camera.position.copy(p.normalize().multiplyScalar(transition.a+(transition.b-transition.a)*ease));if(t===1)transition=null;}controls.update(dt);camera.updateMatrixWorld();
 const d=camera.position.length(),detail=true,boxes=[];const sorted=[...markers].sort((a,b)=>(b.u.id===selected?.id)-(a.u.id===selected?.id)||Number(!!b.u.logo)-Number(!!a.u.logo));for(const m of sorted){const projected=m.pos.clone().project(camera),front=m.pos.dot(camera.position)>1.035;const x=(projected.x*.5+.5)*view.clientWidth,y=(-projected.y*.5+.5)*view.clientHeight;let show=front&&projected.z<1&&x>18&&x<view.clientWidth-18&&y>18&&y<view.clientHeight-90;const useDetail=detail&&(matches(m.u)||m.u.id===selected?.id),size=useDetail?(m.u.logo?82:70):18;const box={x,y,size};if(show&&boxes.some(b=>Math.abs(b.x-x)<(b.size+size)/2&&Math.abs(b.y-y)<(b.size+size)/2))show=false;if(show)boxes.push(box);m.b.style.display=show?'flex':'none';m.b.style.left=x+'px';m.b.style.top=y+'px';m.b.style.opacity=matches(m.u)?String(reduce.matches?1:Math.min(1,(now-born)/1200)):'0.2';m.b.classList.toggle('detailed',useDetail);m.b.classList.toggle('selected',m.u.id===selected?.id);}
 lines.forEach((line,i)=>{line.material.opacity=reduce.matches?.24:Math.min(.27,Math.max(0,(now-born-900-i*100)/2000)*.27);line.geometry.setDrawRange(0,reduce.matches?91:Math.min(91,Math.max(0,Math.floor((now-born-900-i*100)/18))));if(activeMotion())line.material.dashSize=.032+Math.sin(now/2000+i)*.005;});renderer.render(scene,camera);}
 requestAnimationFrame(frame);if(!reduce.matches&&region==='All'&&!input.value)flyTo(30,-65,view.clientWidth<500?5.8:4.2);else if(selected)flyTo(selected.lat,selected.lng,2.05);else flyTo(...centers[region]);
}
